const n13=node({type:"n8n-nodes-base.code",version:2,config:{"name":"OPURO — Resolver categoría","parameters":{"jsCode":"const c=$('Validar y normalizar OPMX MASTER').first().json.canonical;\nconst requested=String(c.categories?.opuro?.principal ?? c.category ?? '').trim();\nif(!requested) throw new Error('El JSON MASTER no entregó la categoría principal para OPURO.');\n\nconst norm=s=>String(s??'')\n  .normalize('NFD').replace(/[\\u0300-\\u036f]/g,'')\n  .replace(/\\s+/g,' ')\n  .trim().toLocaleLowerCase('es-MX');\n\nconst rows=$input.all().map(i=>i.json).flatMap(x=>Array.isArray(x)?x:[x]);\nconst exact=rows.find(x=>norm(x.name)===norm(requested));\n\nif(!exact?.id){\n  const available=rows.map(x=>`${x.name??'(sin nombre)'} [slug ${x.slug??'?'} | ID ${x.id??'?'}]`).join(', ');\n  throw new Error(`La categoría \"${requested}\" no existe como coincidencia exacta por nombre en Oxígeno Puro. Categorías recibidas de WordPress: ${available||'ninguna'}.`);\n}\nreturn [{json:{\n  category_id:Number(exact.id),\n  category_name:exact.name,\n  category_slug:exact.slug??null,\n  requested_category:requested,\n  resolution:'EXACT_NORMALIZED_NAME_MATCH'\n}}];"},"onError":"stopWorkflow"}});
const n14=node({type:"n8n-nodes-base.code",version:2,config:{"name":"OPURO — Preparar etiquetas v1.13","parameters":{"jsCode":"const c=$('Validar y normalizar OPMX MASTER').first().json.canonical;\nconst tags=Array.isArray(c.tags)?c.tags.map(x=>String(x).trim()).filter(Boolean):[];\nif(!tags.length) throw new Error('SEO.ETIQUETAS está vacío.');\n\nconst norm=s=>String(s??'')\n  .normalize('NFD').replace(/[\\u0300-\\u036f]/g,'')\n  .trim().toLocaleLowerCase('es-MX');\n\nconst slugify=s=>norm(s)\n  .replace(/[^a-z0-9]+/g,'-')\n  .replace(/^-+|-+$/g,'');\n\nconst seen=new Set();\nconst out=[];\n\nfor(const name of tags){\n  const key=norm(name);\n  if(!key || seen.has(key)) continue;\n  seen.add(key);\n  out.push({json:{\n    tag_index:out.length,\n    tag_name:name,\n    tag_slug:slugify(name)\n  }});\n}\nreturn out;"},"onError":"stopWorkflow"}});
