const n21=node({type:"n8n-nodes-base.code",version:2,config:{"name":"OPURO — Consolidar etiquetas v1.13","parameters":{"jsCode":"const expected=$('OPURO — Preparar etiquetas v1.13').all().length;\nconst state=$getWorkflowStaticData('global');\nconst executionId=String($execution.id ?? 'execution');\nconst resultKey=`opmx_tag_results:${executionId}:opuro`;\nconst rows=(Array.isArray(state[resultKey]) ? state[resultKey] : [])\n  .filter(x=>Number(x?.tag_id)>0)\n  .sort((a,b)=>Number(a.tag_index)-Number(b.tag_index));\n\nif(rows.length!==expected){\n  throw new Error(`Etiquetas incompletas: esperadas ${expected}, resueltas ${rows.length}.`);\n}\n\nconst ids=[];\nconst seen=new Set();\nfor(const row of rows){\n  const id=Number(row.tag_id);\n  if(!seen.has(id)){\n    seen.add(id);\n    ids.push(id);\n  }\n}\n\ndelete state[resultKey];\n\nreturn [{json:{\n  tag_ids:ids,\n  tags_resolved:rows,\n  tags_count:ids.length\n}}];"},"onError":"stopWorkflow"}});
