const n25=node({type:"n8n-nodes-base.code",version:2,config:{"name":"OPURO — Validar antes de publicar","parameters":{"mode":"runOnceForEachItem","jsCode":"const p=$json;\nconst c=$('Validar y normalizar OPMX MASTER').first().json.canonical;\nconst expectedTags=$('OPURO — Consolidar etiquetas v1.13').first().json.tag_ids.map(Number).sort((a,b)=>a-b);\nconst actualTags=Array.isArray(p.tags)?p.tags.map(Number).sort((a,b)=>a-b):null;\nif(String(p.slug??'')!==c.slug) throw new Error('OPURO slug no coincide.');\nif(String(p?.meta?.oxpuro_editorial?.subtitle??'')!==String(c.subtitle??'')) throw new Error('OPURO subtítulo no coincide.');\nif(String(p?.meta?.oxpuro_editorial?.photo_credit??'')!==String(c.images.hero_opuro.credit??'')) throw new Error('OPURO crédito de Hero no coincide.');\nif(Number(p.author)!==Number(c.author.id)) throw new Error('OPURO autor no coincide.');\nif(String(p?.title?.raw??'')!==c.title) throw new Error('OPURO título no coincide.');\nif(!actualTags || JSON.stringify(actualTags)!==JSON.stringify(expectedTags)) throw new Error('OPURO etiquetas no coinciden.');\nfor(const [key,value] of [['rank_math_title',c.title],['rank_math_description',c.meta_description],['rank_math_focus_keyword',c.keywords_all]]) {\n  if(String(p?.meta?.[key]??'')!==String(value??'')) throw new Error('OPURO SEO no coincide: '+key);\n}\nif(typeof p?.content?.raw!=='string' || p.content.raw!==c.gutenberg_enriquecido_final) throw new Error('OPURO Gutenberg no coincide en readback.');\nconst expectedFeatured=Number($('OPURO — Subir DESTACADA').first().json.id);\nconst expectedCat=Number($('OPURO — Resolver categoría').first().json.category_id);\nconst expectedHero=Number($('OPURO — Subir HERO').first().json.id);\nif(!p?.id) throw new Error('OPURO readback no devolvió ID.');\nif(String(p.status)!=='draft') throw new Error(`OPURO no está en draft antes de publicar. Estado: ${p.status}`);\nif(!Number.isSafeInteger(expectedHero) || expectedHero < 1 || Number(p?.meta?.oxpuro_hero_media_id)!==expectedHero) throw new Error('OPURO HERO no coincide con el adjunto cargado.');\nif(Number(p.featured_media)!==expectedFeatured) throw new Error(`OPURO featured_media no coincide. Esperado ${expectedFeatured}, recibido ${p.featured_media}.`);\nif(!Array.isArray(p.categories)||!p.categories.map(Number).includes(expectedCat)) throw new Error('OPURO no confirmó la categoría esperada.');\nconst content=String(p?.content?.raw ?? p?.content?.rendered ?? '');\nif(!content || content.includes('{{OPMX:HERO_OPURO}}')) throw new Error('OPURO conserva placeholder HERO o contenido vacío.');\nreturn {json:{validated:true,post_id:Number(p.id)}};"},"onError":"stopWorkflow"}});
